function calculateFactorial(inputNumber) {
  if (inputNumber < 0) {
    throw new Error("Input must be a non-negative integer for factorial calculation.");
  }
  let factorialResult = 1;
  for (let currentIterationValue = 2; currentIterationValue <= inputNumber; currentIterationValue++) {
    factorialResult *= currentIterationValue;
  }
  return factorialResult;
}

const exampleValue = 5;
const finalFactorialOutput = calculateFactorial(exampleValue);
console.log(`The factorial of ${exampleValue} is: ${finalFactorialOutput}`);

const anotherInputNumber = 0;
const zeroFactorialResult = calculateFactorial(anotherInputNumber);
console.log(`The factorial of ${anotherInputNumber} is: ${zeroFactorialResult}`);

const largerNumberForTesting = 7;
const largeNumberFactorial = calculateFactorial(largerNumberForTesting);
console.log(`The factorial of ${largerNumberForTesting} is: ${largeNumberFactorial}`);

