const convertCelsiusToFahrenheit = (celsiusTemperature) => {
  const conversionFactorNumerator = 9;
  const conversionFactorDenominator = 5;
  const fahrenheitOffsetValue = 32;

  const fahrenheitResult = (celsiusTemperature * conversionFactorNumerator / conversionFactorDenominator) + fahrenheitOffsetValue;

  return fahrenheitResult;
};

const celsiusToFahrenheit = (inputCelsiusValue) => {
  const fahrenheitEquivalent = convertCelsiusToFahrenheit(inputCelsiusValue);
  return fahrenheitEquivalent;
};

// Example usage and testing
const freezingPointCelsius = 0;
const freezingPointFahrenheit = celsiusToFahrenheit(freezingPointCelsius); // Should be 32

const roomTemperatureCelsius = 25;
const roomTemperatureFahrenheit = celsiusToFahrenheit(roomTemperatureCelsius); // Should be 77

const boilingPointCelsius = 100;
const boilingPointFahrenheit = celsiusToFahrenheit(boilingPointCelsius); // Should be 212

