function removeDuplicates(inputArray) {
  const uniqueElementsSet = new Set();
  const resultingNewArray = [];

  for (const currentElement of inputArray) {
    if (!uniqueElementsSet.has(currentElement)) {
      uniqueElementsSet.add(currentElement);
      resultingNewArray.push(currentElement);
    }
  }

  return resultingNewArray;
}

function processAndDisplayResult(originalCollection) {
  const finalProcessedArray = removeDuplicates(originalCollection);
  console.log("Original array:", originalCollection);
  console.log("Array with unique values:", finalProcessedArray);
}

// Example usage with various data types
processAndDisplayResult([1, 2, 2, 3, 1]);
processAndDisplayResult(['apple', 'banana', 'apple', 'orange', 'banana']);
processAndDisplayResult([true, false, true, false, true]);
processAndDisplayResult([null, undefined, null, 1, undefined]);

