function simpleCalculator(firstNumber, mathOperator, secondNumber) {
  let operationResult;
  switch (mathOperator) {
    case '+':
      operationResult = firstNumber + secondNumber;
      break;
    case '-':
      operationResult = firstNumber - secondNumber;
      break;
    case '*':
      operationResult = firstNumber * secondNumber;
      break;
    case '/':
      if (secondNumber === 0) {
        return null;
      }
      operationResult = firstNumber / secondNumber;
      break;
    default:
      return null;
  }
  return operationResult;
}

const calculateSum = (valueOne, valueTwo) => simpleCalculator(valueOne, '+', valueTwo);
