function findLongestWord(inputSentence) {
  const wordsArray = inputSentence.split(' ');
  let longestWordFound = '';
  let maximumWordLength = 0;

  for (let i = 0; i < wordsArray.length; i++) {
    const currentWord = wordsArray[i];
    const currentWordLength = currentWord.length;

    if (currentWordLength > maximumWordLength) {
      maximumWordLength = currentWordLength;
      longestWordFound = currentWord;
    }
  }
  return longestWordFound;
}

