const areAnagrams = (firstString, secondString) => {
  const normalizeAndSort = (inputStringValue) => {
    const trimmedLowerCase = inputStringValue.toLowerCase().replace(/\s/g, '');
    const characterArray = Array.from(trimmedLowerCase);
    const sortedCharacterArray = characterArray.sort();
    const sortedStringRepresentation = sortedCharacterArray.join('');
    return sortedStringRepresentation;
  };

  const normalizedFirstString = normalizeAndSort(firstString);
  const normalizedSecondString = normalizeAndSort(secondString);

  const areStringRepresentationsEqual = normalizedFirstString === normalizedSecondString;
  return areStringRepresentationsEqual;
};

