function calculateAge(birthdateStringInput) {
  const birthDate = new Date(birthdateStringInput);
  const todayDate = new Date();

  let yearsDifference = todayDate.getFullYear() - birthDate.getFullYear();
  const monthDifference = todayDate.getMonth() - birthDate.getMonth();
  const dayDifference = todayDate.getDate() - birthDate.getDate();

  if (monthDifference < 0 || (monthDifference === 0 && dayDifference < 0)) {
    yearsDifference--;
  }

  const finalCalculatedAge = Math.max(0, yearsDifference);
  return finalCalculatedAge;
}

