const playRockPaperScissors = (playerSelection) => {
  const possibleMoves = ['rock', 'paper', 'scissors'];
  const computerSelectionIndex = Math.floor(Math.random() * possibleMoves.length);
  const computerSelection = possibleMoves[computerSelectionIndex];

  if (playerSelection === computerSelection) {
    return 'Tie';
  }

  const didPlayerWin =
    (playerSelection === 'rock' && computerSelection === 'scissors') ||
    (playerSelection === 'paper' && computerSelection === 'rock') ||
    (playerSelection === 'scissors' && computerSelection === 'paper');

  if (didPlayerWin) {
    return 'Win';
  } else {
    return 'Loss';
  }
};

