function truncateString(inputString, maximumLength) {
  if (inputString.length <= maximumLength) {
    return inputString;
  }

  const truncationIndicator = '...';
  const effectiveMaxLength = maximumLength - truncationIndicator.length;

  if (effectiveMaxLength < 0) {
    return truncationIndicator.substring(0, maximumLength); // Handle very small maxLength
  }

  const truncatedPart = inputString.substring(0, effectiveMaxLength);
  const finalResult = truncatedPart + truncationIndicator;

  return finalResult;
}

