function daysBetweenDates(firstDateString, secondDateString) {
  const millisecondsPerDay = 1000 * 60 * 60 * 24;
  const initialDate = new Date(firstDateString);
  const finalDate = new Date(secondDateString);

  const initialDateTime = initialDate.getTime();
  const finalDateTime = finalDate.getTime();

  const timeDifferenceInMilliseconds = Math.abs(finalDateTime - initialDateTime);
  const calculatedDaysDifference = Math.round(timeDifferenceInMilliseconds / millisecondsPerDay);

  return calculatedDaysDifference;
}

