const compressString = (originalString) => {
  let compressedStringResult = '';
  let currentCharIndex = 0;

  while (currentCharIndex < originalString.length) {
    let currentCharacter = originalString[currentCharIndex];
    let characterRepeatCount = 0;
    let lookAheadIndex = currentCharIndex;

    while (lookAheadIndex < originalString.length && originalString[lookAheadIndex] === currentCharacter) {
      characterRepeatCount++;
      lookAheadIndex++;
    }

    compressedStringResult += currentCharacter;
    if (characterRepeatCount > 1) {
      compressedStringResult += characterRepeatCount.toString();
    }
    currentCharIndex = lookAheadIndex;
  }

  return compressedStringResult.length < originalString.length ? compressedStringResult : originalString;
};

