const findSecondSmallest = (inputArray) => {
  if (inputArray.length < 2) {
    throw new Error("Array must contain at least two numbers.");
  }

  let smallestNumber = Infinity;
  let secondSmallestNumber = Infinity;

  for (let currentNumber of inputArray) {
    if (currentNumber < smallestNumber) {
      secondSmallestNumber = smallestNumber;
      smallestNumber = currentNumber;
    } else if (currentNumber < secondSmallestNumber && currentNumber !== smallestNumber) {
      secondSmallestNumber = currentNumber;
    }
  }

  if (secondSmallestNumber === Infinity) {
    throw new Error("Unable to find a distinct second smallest number.");
  }

  return secondSmallestNumber;
};

