      return full_file_name.substring(last_dot_index + 1);
  }

  return full_file_name.substring(last_dot_index + 1);
};

const get_file_extension = (input_file_name) => {
  const dot_position = input_file_name.lastIndexOf('.');
  const no_extension_found = -1;

  if (dot_position === no_extension_found || dot_position === 0 || dot_position === input_file_name.length - 1) {
    return '';
  }

  const potential_extension = input_file_name.substring(dot_position + 1);
  const contains_another_dot = potential_extension.includes('.');

  if (contains_another_dot) {
    const last_part_after_second_dot = potential_extension.substring(potential_extension.lastIndexOf('.') + 1);
    return last_part_after_second_dot;
  }

  return potential_extension;
};

