const calculateBMI = (patientWeightInKg, patientHeightInMeters) => {
  const minimumHeight = 0.5;
  const maximumHeight = 2.5;
  const minimumWeight = 20;
  const maximumWeight = 200;

  if (patientHeightInMeters < minimumHeight || patientHeightInMeters > maximumHeight || patientWeightInKg < minimumWeight || patientWeightInKg > maximumWeight) {
    console.error("Input values are outside of a reasonable range for a human body mass index calculation.");
    return null;
  }

  const heightSquared = patientHeightInMeters * patientHeightInMeters;
  const bodyMassIndexValue = patientWeightInKg / heightSquared;
  const formattedBmiResult = parseFloat(bodyMassIndexValue.toFixed(2));
  return formattedBmiResult;
};

const firstPersonBmi = calculateBMI(70, 1.75);
const secondPersonBmi = calculateBMI(90, 1.80);
const thirdPersonBmi = calculateBMI(65, 1.65);
const invalidPersonBmi = calculateBMI(10, 1.5);

console.log(firstPersonBmi);
console.log(secondPersonBmi);
console.log(thirdPersonBmi);
console.log(invalidPersonBmi);

